package config

import (
	"fmt"
	"net"
	"os"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// Duration is a yaml-friendly time.Duration ("30s", "5m", "720h").
type Duration time.Duration

func (d *Duration) UnmarshalYAML(node *yaml.Node) error {
	var s string
	if err := node.Decode(&s); err != nil {
		return err
	}
	if s == "" {
		*d = 0
		return nil
	}
	v, err := time.ParseDuration(s)
	if err != nil {
		return fmt.Errorf("invalid duration %q: %w", s, err)
	}
	*d = Duration(v)
	return nil
}

func (d Duration) D() time.Duration { return time.Duration(d) }

type Config struct {
	Listen      string   `yaml:"listen"`
	Interval    Duration `yaml:"interval"`
	Timeout     Duration `yaml:"timeout"`
	Count       int      `yaml:"count"`
	Concurrency int      `yaml:"concurrency"`
	DB          string   `yaml:"db"`
	Retention   Duration `yaml:"retention"`
	Demo        bool     `yaml:"demo"`
	VLANS       []VLAN   `yaml:"vlans"`
	Targets     Targets  `yaml:"targets"`
	Policy      Policy   `yaml:"policy"`
	Alerts      Alerts   `yaml:"alerts"`
}

type VLAN struct {
	Name    string `yaml:"name" json:"name"`
	VLANID  int    `yaml:"vlan_id" json:"vlan_id"`
	Iface   string `yaml:"iface" json:"iface"`
	Src     string `yaml:"src" json:"src"`
	Gateway string `yaml:"gateway" json:"gateway"`
}

func (v VLAN) SrcIP() string {
	ip, _, err := net.ParseCIDR(v.Src)
	if err != nil {
		return ""
	}
	return ip.String()
}

func (v VLAN) Subnet() string {
	_, n, err := net.ParseCIDR(v.Src)
	if err != nil {
		return ""
	}
	return n.String()
}

type Targets struct {
	// Mode "gateway" probes each VLAN gateway (the firewall itself).
	// Mode "hosts" probes the host listed in Hosts[<vlan name>] (fallback: gateway).
	Mode  string            `yaml:"mode" json:"mode"`
	Hosts map[string]string `yaml:"hosts" json:"hosts"`
}

func (t Targets) For(src VLAN) string {
	if t.Mode == "hosts" {
		if h, ok := t.Hosts[src.Name]; ok && h != "" {
			return h
		}
	}
	return src.Gateway
}

type Policy struct {
	Default string `yaml:"default" json:"default"`
	Rules   []Rule `yaml:"rules" json:"rules"`
}

type Rule struct {
	From   string `yaml:"from" json:"from"`
	To     string `yaml:"to" json:"to"`
	Action string `yaml:"action" json:"action"`
}

// Expected returns the intended action ("allow"/"deny") for a directed pair.
// Wildcards "*" are supported for From and To.
func (p Policy) Expected(from, to string) (string, bool) {
	for _, r := range p.Rules {
		f := r.From == "*" || r.From == from
		t := r.To == "*" || r.To == to
		if f && t {
			return r.Action, true
		}
	}
	if p.Default == "allow" || p.Default == "deny" {
		return p.Default, true
	}
	return "", false
}

type Alerts struct {
	Webhook string `yaml:"webhook" json:"webhook"`
}

func Load(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Config
	if err := yaml.Unmarshal(b, &c); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	c.applyDefaults()
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return &c, nil
}

func (c *Config) applyDefaults() {
	if c.Listen == "" {
		c.Listen = ":8080"
	}
	if c.Interval == 0 {
		c.Interval = Duration(30 * time.Second)
	}
	if c.Timeout == 0 {
		c.Timeout = Duration(time.Second)
	}
	if c.Count == 0 {
		c.Count = 3
	}
	if c.Concurrency == 0 {
		c.Concurrency = 8
	}
	if c.DB == "" {
		c.DB = "/data/vlanmesh.db"
	}
	if c.Retention == 0 {
		c.Retention = Duration(720 * time.Hour)
	}
	if c.Targets.Mode == "" {
		c.Targets.Mode = "gateway"
	}
	if c.Targets.Hosts == nil {
		c.Targets.Hosts = map[string]string{}
	}
}

func (c *Config) Validate() error {
	if c.Interval.D() < time.Second {
		return fmt.Errorf("interval must be >= 1s")
	}
	if c.Timeout.D() <= 0 {
		return fmt.Errorf("timeout must be > 0")
	}
	if c.Count < 1 || c.Count > 20 {
		return fmt.Errorf("count must be between 1 and 20")
	}
	if c.Concurrency < 1 {
		return fmt.Errorf("concurrency must be >= 1")
	}
	if c.Targets.Mode != "gateway" && c.Targets.Mode != "hosts" {
		return fmt.Errorf("targets.mode must be \"gateway\" or \"hosts\"")
	}
	if c.Policy.Default != "" && c.Policy.Default != "allow" && c.Policy.Default != "deny" {
		return fmt.Errorf("policy.default must be \"allow\", \"deny\" or empty")
	}
	for i, r := range c.Policy.Rules {
		if r.Action != "allow" && r.Action != "deny" {
			return fmt.Errorf("policy.rules[%d]: action must be \"allow\" or \"deny\"", i)
		}
		if r.From == "" || r.To == "" {
			return fmt.Errorf("policy.rules[%d]: from/to are required (use \"*\" for any)", i)
		}
	}
	if len(c.VLANS) == 0 {
		return fmt.Errorf("vlans: at least one VLAN is required")
	}
	seen := map[string]bool{}
	for i := range c.VLANS {
		v := &c.VLANS[i]
		if v.Name == "" {
			return fmt.Errorf("vlans[%d]: name is required", i)
		}
		if seen[v.Name] {
			return fmt.Errorf("vlans[%d]: duplicate name %q", i, v.Name)
		}
		seen[v.Name] = true
		if v.Iface == "" {
			return fmt.Errorf("vlans[%d] (%s): iface is required", i, v.Name)
		}
		ip, n, err := net.ParseCIDR(v.Src)
		if err != nil {
			return fmt.Errorf("vlans[%d] (%s): invalid src %q: %w", i, v.Name, v.Src, err)
		}
		if v.Gateway == "" {
			return fmt.Errorf("vlans[%d] (%s): gateway is required", i, v.Name)
		}
		gw := net.ParseIP(v.Gateway)
		if gw == nil {
			return fmt.Errorf("vlans[%d] (%s): invalid gateway %q", i, v.Name, v.Gateway)
		}
		if !n.Contains(gw) {
			return fmt.Errorf("vlans[%d] (%s): gateway %s is outside %s", i, v.Name, v.Gateway, n)
		}
		if !n.Contains(ip) {
			return fmt.Errorf("vlans[%d] (%s): src %s is outside %s", i, v.Name, v.Src, n)
		}
		if ones, _ := n.Mask.Size(); ones > 30 {
			return fmt.Errorf("vlans[%d] (%s): src prefix must be <= /30", i, v.Name)
		}
	}
	return nil
}

// Summary returns a compact human description of a VLAN.
func (v VLAN) Summary() string {
	return fmt.Sprintf("%s (%s, %s via %s)", v.Name, v.Iface, v.Src, v.Gateway)
}

// DisplayName returns name or a fallback based on iface.
func (v VLAN) DisplayName() string {
	if v.Name != "" {
		return v.Name
	}
	return strings.TrimSpace(v.Iface)
}

package probe

import (
	"encoding/binary"
	"errors"
	"fmt"
	"math/rand/v2"
	"net"
	"time"

	"golang.org/x/net/icmp"
	"golang.org/x/net/ipv4"
	"golang.org/x/sys/unix"

	"vlanmesh/internal/model"
)

// Probe sends count ICMP echoes from srcIP (bound to iface) to dstIP and
// returns a classified result.
//
// SO_BINDTODEVICE is mandatory: without it the kernel would route the packet
// straight out of the destination VLAN's leg and bypass the firewall.
func Probe(srcIP, iface, dstIP string, count int, timeout time.Duration) model.Result {
	res := model.Result{
		SrcIP:   srcIP,
		DstIP:   dstIP,
		Started: time.Now(),
	}
	fail := func(err error) model.Result {
		res.Status = model.StatusError
		res.Err = err.Error()
		res.Duration = float64(time.Since(res.Started).Microseconds()) / 1000
		return res
	}

	dst := net.ParseIP(dstIP)
	if dst == nil {
		return fail(fmt.Errorf("invalid destination %q", dstIP))
	}
	src := net.ParseIP(srcIP)
	if src == nil {
		return fail(fmt.Errorf("invalid source %q", srcIP))
	}

	conn, err := net.ListenPacket("ip4:icmp", srcIP)
	if err != nil {
		return fail(fmt.Errorf("raw icmp socket on %s: %w (need CAP_NET_RAW)", srcIP, err))
	}
	defer conn.Close()

	ipc, ok := conn.(*net.IPConn)
	if !ok {
		return fail(fmt.Errorf("unexpected connection type %T", conn))
	}
	if err := bindToDevice(ipc, iface); err != nil {
		return fail(err)
	}

	id := rand.IntN(0xffff)
	payload := []byte("vlanmesh")
	sentAt := make(map[int]time.Time, count)

	for seq := 1; seq <= count; seq++ {
		msg := icmp.Message{
			Type: ipv4.ICMPTypeEcho,
			Code: 0,
			Body: &icmp.Echo{ID: id, Seq: seq, Data: payload},
		}
		b, err := msg.Marshal(nil)
		if err != nil {
			return fail(fmt.Errorf("marshal icmp: %w", err))
		}
		sentAt[seq] = time.Now()
		if _, err := conn.WriteTo(b, &net.IPAddr{IP: dst}); err != nil {
			return fail(fmt.Errorf("send icmp to %s via %s: %w (check policy routing)", dstIP, iface, err))
		}
		res.Sent++
		if seq < count {
			time.Sleep(100 * time.Millisecond)
		}
	}

	deadline := time.Now().Add(timeout)
	_ = conn.SetReadDeadline(deadline)

	var (
		rtts      []float64
		seen      = make(map[int]bool, count)
		icmpType  int
		icmpCode  int
		errText   string
		buf       = make([]byte, 1500)
	)

	for len(seen) < count {
		if time.Now().After(deadline) {
			break
		}
		n, addr, err := conn.ReadFrom(buf)
		if err != nil {
			var ne net.Error
			if errors.As(err, &ne) && ne.Timeout() {
				break
			}
			if time.Now().After(deadline) {
				break
			}
			continue
		}
		now := time.Now()
		m, err := icmp.ParseMessage(1, buf[:n])
		if err != nil {
			continue
		}

		switch body := m.Body.(type) {
		case *icmp.Echo:
			if m.Type != ipv4.ICMPTypeEchoReply {
				continue
			}
			if body.ID != id || body.Seq < 1 || body.Seq > count {
				continue
			}
			if ia, ok := addr.(*net.IPAddr); ok && !ia.IP.Equal(dst) {
				continue
			}
			if seen[body.Seq] {
				continue
			}
			seen[body.Seq] = true
			at, ok := sentAt[body.Seq]
			if !ok {
				at = now
			}
			rtts = append(rtts, float64(now.Sub(at).Microseconds())/1000)

		case *icmp.DstUnreach:
			if pid, seq, ok := innerIDSeq(body.Data); ok && pid == id && seq >= 1 && seq <= count {
				icmpType = int(m.Type)
				icmpCode = m.Code
				errText = fmt.Sprintf("icmp unreachable (type %d code %d)", m.Type, m.Code)
			}

		case *icmp.TimeExceeded:
			if pid, seq, ok := innerIDSeq(body.Data); ok && pid == id && seq >= 1 && seq <= count {
				icmpType = int(m.Type)
				icmpCode = m.Code
				errText = "icmp time exceeded"
			}
		}
	}

	res.Recv = len(seen)
	res.ICMPType = icmpType
	res.ICMPCode = icmpCode
	res.Loss = 1 - float64(res.Recv)/float64(res.Sent)

	if res.Recv > 0 {
		res.RTTMin = rtts[0]
		res.RTTMax = rtts[0]
		var sum float64
		for _, r := range rtts {
			if r < res.RTTMin {
				res.RTTMin = r
			}
			if r > res.RTTMax {
				res.RTTMax = r
			}
			sum += r
		}
		res.RTTAvg = sum / float64(len(rtts))
		if res.Recv == res.Sent {
			res.Status = model.StatusOK
		} else {
			res.Status = model.StatusDegraded
		}
	} else {
		switch {
		case icmpType == 3 && (icmpCode == 9 || icmpCode == 10 || icmpCode == 13):
			res.Status = model.StatusRejected
		case icmpType == 3, icmpType == 11:
			res.Status = model.StatusUnreachable
		default:
			res.Status = model.StatusTimeout
		}
		res.Err = errText
	}

	res.Duration = float64(time.Since(res.Started).Microseconds()) / 1000
	return res
}

func bindToDevice(conn *net.IPConn, iface string) error {
	sc, err := conn.SyscallConn()
	if err != nil {
		return fmt.Errorf("syscall conn: %w", err)
	}
	var soErr error
	if err := sc.Control(func(fd uintptr) {
		soErr = unix.SetsockoptString(int(fd), unix.SOL_SOCKET, unix.SO_BINDTODEVICE, iface)
	}); err != nil {
		return fmt.Errorf("control socket: %w", err)
	}
	if soErr != nil {
		return fmt.Errorf("SO_BINDTODEVICE %s: %w", iface, soErr)
	}
	return nil
}

// innerIDSeq extracts the ICMP ID/seq of the original datagram embedded in an
// ICMP error message.
func innerIDSeq(data []byte) (id, seq int, ok bool) {
	if len(data) < 28 {
		return 0, 0, false
	}
	ihl := int(data[0]&0x0f) * 4
	if ihl < 20 || len(data) < ihl+8 {
		return 0, 0, false
	}
	return int(binary.BigEndian.Uint16(data[ihl+4 : ihl+6])),
		int(binary.BigEndian.Uint16(data[ihl+6 : ihl+8])), true
}

package netcfg

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"vlanmesh/internal/config"
)

// Apply sets up source-based policy routing so a probe sourced from VLAN i
// physically leaves through eth_i (and therefore hits the firewall), instead
// of taking the directly connected route of the destination VLAN.
//
// It is idempotent and best-effort: problems are returned as human readable
// issues so the UI can display them.
func Apply(cfg *config.Config) []string {
	var issues []string

	if _, err := exec.LookPath("ip"); err != nil {
		return append(issues, "iproute2 not found: install `ip` in the container (alpine: apk add iproute2)")
	}

	for i, v := range cfg.VLANS {
		table := Table(i)
		pref := Pref(i)
		srcIP := v.SrcIP()
		subnet := v.Subnet()
		if srcIP == "" || subnet == "" {
			issues = append(issues, fmt.Sprintf("%s: invalid src %q", v.Name, v.Src))
			continue
		}

		if err := run("ip", "link", "show", "dev", v.Iface); err != nil {
			issues = append(issues, fmt.Sprintf("%s: interface %s not found (check Proxmox net%d)", v.Name, v.Iface, i+1))
			continue
		}

		addrOut, err := output("ip", "-4", "-o", "addr", "show", "dev", v.Iface)
		if err != nil || !strings.Contains(addrOut, srcIP+"/") {
			issues = append(issues, fmt.Sprintf("%s: %s is not configured on %s (expected %s)", v.Name, srcIP, v.Iface, v.Src))
		}

		// Connected route inside the per-VLAN table.
		if err := run("ip", "route", "replace", subnet, "dev", v.Iface, "src", srcIP, "table", itoa(table)); err != nil {
			issues = append(issues, fmt.Sprintf("%s: route %s via %s table %d failed: %v", v.Name, subnet, v.Iface, table, err))
		}
		// Default route inside the per-VLAN table -> firewall.
		if err := run("ip", "route", "replace", "default", "via", v.Gateway, "dev", v.Iface, "table", itoa(table)); err != nil {
			issues = append(issues, fmt.Sprintf("%s: default via %s table %d failed: %v", v.Name, v.Gateway, table, err))
		}
		// Policy rule: traffic sourced from this VLAN's IP uses its own table.
		if ok, _ := hasRule(srcIP, table); !ok {
			if err := run("ip", "rule", "add", "from", srcIP, "lookup", itoa(table), "pref", itoa(pref)); err != nil {
				if !strings.Contains(err.Error(), "File exists") {
					issues = append(issues, fmt.Sprintf("%s: ip rule from %s table %d failed: %v", v.Name, srcIP, table, err))
				}
			}
		}

		// Strict rp_filter drops replies coming back on the source VLAN
		// (their reverse route lives on another VLAN). Loose mode (2) is required.
		if v2, err := os.ReadFile("/proc/sys/net/ipv4/conf/" + v.Iface + "/rp_filter"); err == nil {
			if strings.TrimSpace(string(v2)) == "1" {
				if err := os.WriteFile("/proc/sys/net/ipv4/conf/"+v.Iface+"/rp_filter", []byte("2\n"), 0o644); err != nil {
					issues = append(issues, fmt.Sprintf("%s: rp_filter=1 on %s and cannot be changed from the container; run on the LXC: sysctl -w net.ipv4.conf.all.rp_filter=2 net.ipv4.conf.%s.rp_filter=2", v.Name, v.Iface, v.Iface))
				}
			}
		}
	}

	if v, err := os.ReadFile("/proc/sys/net/ipv4/conf/all/rp_filter"); err == nil {
		if strings.TrimSpace(string(v)) == "1" {
			if err := os.WriteFile("/proc/sys/net/ipv4/conf/all/rp_filter", []byte("2\n"), 0o644); err != nil {
				issues = append(issues, "net.ipv4.conf.all.rp_filter=1 and read-only here; run on the LXC: sysctl -w net.ipv4.conf.all.rp_filter=2")
			}
		}
	}

	return issues
}

// Table returns the dedicated routing table number for VLAN index i.
func Table(i int) int { return 100 + i }

// Pref returns the ip rule preference for VLAN index i.
func Pref(i int) int { return 1000 + i }

func hasRule(srcIP string, table int) (bool, error) {
	out, err := output("ip", "rule", "show")
	if err != nil {
		return false, err
	}
	for _, line := range strings.Split(out, "\n") {
		if strings.Contains(line, "from "+srcIP+" ") && strings.Contains(line, "lookup "+itoa(table)) {
			return true, nil
		}
	}
	return false, nil
}

// Commands returns the routing commands that Apply runs, for docs/debug.
func Commands(cfg *config.Config) []string {
	var cmds []string
	for i, v := range cfg.VLANS {
		cmds = append(cmds,
			fmt.Sprintf("ip route replace %s dev %s src %s table %d", v.Subnet(), v.Iface, v.SrcIP(), Table(i)),
			fmt.Sprintf("ip route replace default via %s dev %s table %d", v.Gateway, v.Iface, Table(i)),
			fmt.Sprintf("ip rule add from %s lookup %d pref %d", v.SrcIP(), Table(i), Pref(i)),
		)
	}
	return cmds
}

func run(name string, args ...string) error {
	out, err := exec.Command(name, args...).CombinedOutput()
	if err != nil {
		msg := strings.TrimSpace(string(out))
		if msg != "" {
			return fmt.Errorf("%s: %s", err, msg)
		}
		return err
	}
	return nil
}

func output(name string, args ...string) (string, error) {
	out, err := exec.Command(name, args...).Output()
	return string(out), err
}

func itoa(n int) string {
	return fmt.Sprintf("%d", n)
}

package store

import (
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"time"

	_ "modernc.org/sqlite"

	"vlanmesh/internal/model"
)

type Store struct {
	db *sql.DB
}

const schema = `
CREATE TABLE IF NOT EXISTS probes (
	id         INTEGER PRIMARY KEY AUTOINCREMENT,
	ts         INTEGER NOT NULL,
	src        TEXT    NOT NULL,
	dst        TEXT    NOT NULL,
	src_ip     TEXT    NOT NULL,
	dst_ip     TEXT    NOT NULL,
	status     TEXT    NOT NULL,
	sent       INTEGER NOT NULL,
	recv       INTEGER NOT NULL,
	loss       REAL    NOT NULL,
	rtt_min    REAL    NOT NULL,
	rtt_avg    REAL    NOT NULL,
	rtt_max    REAL    NOT NULL,
	icmp_type  INTEGER NOT NULL,
	icmp_code  INTEGER NOT NULL,
	err        TEXT    NOT NULL,
	expected   TEXT    NOT NULL,
	violation  TEXT    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_probes_pair_ts ON probes(src, dst, ts DESC);
CREATE INDEX IF NOT EXISTS idx_probes_ts ON probes(ts);
`

func Open(path string) (*Store, error) {
	if dir := filepath.Dir(path); dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return nil, err
		}
	}
	dsn := fmt.Sprintf("file:%s?_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)&_pragma=synchronous(NORMAL)", path)
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("init schema: %w", err)
	}
	return &Store{db: db}, nil
}

func (s *Store) Close() error { return s.db.Close() }

func (s *Store) Insert(cells []model.Cell) error {
	if len(cells) == 0 {
		return nil
	}
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	stmt, err := tx.Prepare(`INSERT INTO probes
		(ts, src, dst, src_ip, dst_ip, status, sent, recv, loss,
		 rtt_min, rtt_avg, rtt_max, icmp_type, icmp_code, err, expected, violation)
		VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
	if err != nil {
		tx.Rollback()
		return err
	}
	defer stmt.Close()
	for _, c := range cells {
		ts := c.CheckedAt
		if ts.IsZero() {
			ts = time.Now()
		}
		if _, err := stmt.Exec(
			ts.UnixMilli(), c.Src, c.Dst, c.SrcIP, c.DstIP, string(c.Status),
			c.Sent, c.Recv, c.Loss, c.RTTMin, c.RTTAvg, c.RTTMax,
			c.ICMPType, c.ICMPCode, c.Err, c.Expected, c.Violation,
		); err != nil {
			tx.Rollback()
			return err
		}
	}
	return tx.Commit()
}

const columns = `ts, src, dst, src_ip, dst_ip, status, sent, recv, loss,
	rtt_min, rtt_avg, rtt_max, icmp_type, icmp_code, err, expected, violation`

func (s *Store) LatestAll() ([]model.Cell, error) {
	q := `SELECT ` + columns + ` FROM probes p
		WHERE ts = (SELECT MAX(ts) FROM probes q WHERE q.src = p.src AND q.dst = p.dst)`
	rows, err := s.db.Query(q)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []model.Cell
	for rows.Next() {
		c, err := scan(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

func (s *Store) History(src, dst string, limit int) ([]model.Cell, error) {
	if limit <= 0 || limit > 5000 {
		limit = 500
	}
	q := `SELECT ` + columns + ` FROM probes WHERE src = ? AND dst = ? ORDER BY ts DESC LIMIT ?`
	rows, err := s.db.Query(q, src, dst, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []model.Cell
	for rows.Next() {
		c, err := scan(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

func (s *Store) Prune(before time.Time) error {
	_, err := s.db.Exec(`DELETE FROM probes WHERE ts < ?`, before.UnixMilli())
	return err
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scan(r rowScanner) (model.Cell, error) {
	var (
		c         model.Cell
		ts        int64
		status    string
		icmpType  int
		icmpCode  int
		errText   string
		expected  string
		violation string
	)
	err := r.Scan(
		&ts, &c.Src, &c.Dst, &c.SrcIP, &c.DstIP, &status,
		&c.Sent, &c.Recv, &c.Loss, &c.RTTMin, &c.RTTAvg, &c.RTTMax,
		&icmpType, &icmpCode, &errText, &expected, &violation,
	)
	if err != nil {
		return c, err
	}
	c.Status = model.Status(status)
	c.ICMPType = icmpType
	c.ICMPCode = icmpCode
	c.Err = errText
	c.Expected = expected
	c.Violation = violation
	c.CheckedAt = time.UnixMilli(ts)
	return c, nil
}

package metrics

import "github.com/prometheus/client_golang/prometheus"

// Registry is a dedicated registry so we don't leak Go runtime metrics by
// default (they are still exposed under /metrics via the default collector if
// wanted).
var Registry = prometheus.NewRegistry()

var (
	ProbeSuccess = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "vlanmesh_probe_success",
		Help: "1 if the directed probe is reachable (ok or degraded), else 0.",
	}, []string{"src", "dst"})

	ProbeLoss = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "vlanmesh_probe_loss_ratio",
		Help: "ICMP loss ratio of the last probe (0..1).",
	}, []string{"src", "dst"})

	ProbeRTT = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "vlanmesh_probe_rtt_ms",
		Help: "ICMP round-trip time in milliseconds (stat=min|avg|max).",
	}, []string{"src", "dst", "stat"})

	ProbeStatus = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "vlanmesh_probe_status",
		Help: "Current status of a directed probe, 1 for the active status label.",
	}, []string{"src", "dst", "status"})

	PolicyViolation = prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "vlanmesh_policy_violation",
		Help: "1 when the observed result contradicts the expected policy.",
	}, []string{"src", "dst", "type"})

	LastSweep = prometheus.NewGauge(prometheus.GaugeOpts{
		Name: "vlanmesh_last_sweep_timestamp_seconds",
		Help: "Unix timestamp of the last completed sweep.",
	})

	SweepDuration = prometheus.NewGauge(prometheus.GaugeOpts{
		Name: "vlanmesh_sweep_duration_seconds",
		Help: "Duration of the last sweep.",
	})

	SweepsTotal = prometheus.NewCounter(prometheus.CounterOpts{
		Name: "vlanmesh_sweeps_total",
		Help: "Total number of completed sweeps.",
	})

	CellsTotal = prometheus.NewGauge(prometheus.GaugeOpts{
		Name: "vlanmesh_cells_total",
		Help: "Number of directed cells in the matrix.",
	})
)

func init() {
	Registry.MustRegister(ProbeSuccess, ProbeLoss, ProbeRTT, ProbeStatus, PolicyViolation,
		LastSweep, SweepDuration, SweepsTotal, CellsTotal)
}

package monitor

import (
	"bytes"
	"context"
	"encoding/json"
	"log/slog"
	"math/rand/v2"
	"net/http"
	"sort"
	"sync"
	"sync/atomic"
	"time"

	"vlanmesh/internal/config"
	"vlanmesh/internal/metrics"
	"vlanmesh/internal/model"
	"vlanmesh/internal/probe"
	"vlanmesh/internal/store"
)

type Monitor struct {
	cfg    *config.Config
	st     *store.Store
	issues []string
	client *http.Client

	mu            sync.RWMutex
	cells         map[model.Key]model.Cell
	lastSweep     time.Time
	sweeps        uint64
	prevStatus    map[model.Key]model.Status
	prevViolation map[model.Key]string

	running atomic.Bool
}

func New(cfg *config.Config, st *store.Store, issues []string) *Monitor {
	return &Monitor{
		cfg:           cfg,
		st:            st,
		issues:        issues,
		client:        &http.Client{Timeout: 5 * time.Second},
		cells:         map[model.Key]model.Cell{},
		prevStatus:    map[model.Key]model.Status{},
		prevViolation: map[model.Key]string{},
	}
}

// Prime loads the last known state from the database so the UI is not empty
// after a restart.
func (m *Monitor) Prime() {
	cells, err := m.st.LatestAll()
	if err != nil {
		slog.Warn("load last state", "err", err)
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, c := range cells {
		m.cells[model.Key{Src: c.Src, Dst: c.Dst}] = c
	}
	slog.Info("loaded previous state", "cells", len(cells))
}

func (m *Monitor) Run(ctx context.Context) {
	m.Sweep(ctx)
	ticker := time.NewTicker(m.cfg.Interval.D())
	defer ticker.Stop()
	prune := time.NewTicker(time.Hour)
	defer prune.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			m.Sweep(ctx)
		case <-prune.C:
			if err := m.st.Prune(time.Now().Add(-m.cfg.Retention.D())); err != nil {
				slog.Warn("prune history", "err", err)
			}
		}
	}
}

type job struct {
	src     config.VLAN
	dst     config.VLAN
	dstIP   string
	control bool
}

func (m *Monitor) Sweep(ctx context.Context) {
	if !m.running.CompareAndSwap(false, true) {
		slog.Warn("sweep still running, skipping tick")
		return
	}
	defer m.running.Store(false)
	if ctx.Err() != nil {
		return
	}

	started := time.Now()
	jobs := m.buildJobs()

	results := make([]model.Result, len(jobs))
	sem := make(chan struct{}, m.cfg.Concurrency)
	var wg sync.WaitGroup
	for idx := range jobs {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()

			j := jobs[idx]
			var r model.Result
			if m.cfg.Demo {
				r = m.demoResult(j)
			} else {
				r = probe.Probe(j.src.SrcIP(), j.src.Iface, j.dstIP, m.cfg.Count, m.cfg.Timeout.D())
			}
			r.Src = j.src.Name
			r.Dst = j.dst.Name
			if r.SrcIP == "" {
				r.SrcIP = j.src.SrcIP()
			}
			if r.DstIP == "" {
				r.DstIP = j.dstIP
			}
			results[idx] = r
		}(idx)
	}
	wg.Wait()

	now := time.Now()
	controls := make(map[string]bool, len(m.cfg.VLANS))
	for i, j := range jobs {
		if j.control {
			controls[j.src.Name] = results[i].Status.Reachable()
		}
	}

	cells := make([]model.Cell, len(jobs))
	for i, j := range jobs {
		c := model.Cell{Result: results[i], CheckedAt: now}
		if !j.control {
			exp, _ := m.cfg.Policy.Expected(j.src.Name, j.dst.Name)
			c.Expected = exp

			if !controls[j.src.Name] {
				c.Status = model.StatusUnknown
				if c.Err == "" {
					c.Err = "control probe to own gateway failed"
				}
				c.Loss = 1
			} else if exp != "" {
				reach := c.Status.Reachable()
				switch {
				case exp == "allow" && !reach:
					c.Violation = "unexpected_deny"
				case exp == "deny" && reach:
					c.Violation = "unexpected_allow"
				}
			}
		}
		cells[i] = c
	}

	if err := m.st.Insert(cells); err != nil {
		slog.Error("persist sweep", "err", err)
	}

	changes := m.commit(cells, now)
	m.updateMetrics(cells, now.Sub(started))
	m.notify(changes, now)

	slog.Info("sweep done", "cells", len(cells), "duration", time.Since(started).Round(time.Millisecond))
}

func (m *Monitor) buildJobs() []job {
	vlans := m.cfg.VLANS
	jobs := make([]job, 0, len(vlans)*len(vlans))
	for i := range vlans {
		for j := range vlans {
			src := vlans[i]
			dst := vlans[j]
			j := job{src: src, dst: dst, control: i == j}
			if i == j {
				// Control probe: own gateway, on-link, never crosses the firewall.
				j.dstIP = src.Gateway
			} else {
				j.dstIP = m.cfg.Targets.For(dst)
			}
			jobs = append(jobs, j)
		}
	}
	return jobs
}

// commit swaps the in-memory state and returns the cells whose status changed.
func (m *Monitor) commit(cells []model.Cell, at time.Time) []model.Cell {
	m.mu.Lock()
	defer m.mu.Unlock()

	next := make(map[model.Key]model.Cell, len(cells))
	var changes []model.Cell
	for _, c := range cells {
		k := model.Key{Src: c.Src, Dst: c.Dst}
		next[k] = c
		if old, ok := m.cells[k]; ok && old.Status != c.Status {
			changes = append(changes, c)
		}
	}
	m.cells = next
	m.lastSweep = at
	m.sweeps++
	return changes
}

func (m *Monitor) updateMetrics(cells []model.Cell, dur time.Duration) {
	m.mu.Lock()
	defer m.mu.Unlock()

	for _, c := range cells {
		k := model.Key{Src: c.Src, Dst: c.Dst}
		reachable := c.Status.Reachable()
		v := 0.0
		if reachable {
			v = 1
		}
		metrics.ProbeSuccess.WithLabelValues(c.Src, c.Dst).Set(v)
		metrics.ProbeLoss.WithLabelValues(c.Src, c.Dst).Set(c.Loss)
		metrics.ProbeRTT.WithLabelValues(c.Src, c.Dst, "min").Set(c.RTTMin)
		metrics.ProbeRTT.WithLabelValues(c.Src, c.Dst, "avg").Set(c.RTTAvg)
		metrics.ProbeRTT.WithLabelValues(c.Src, c.Dst, "max").Set(c.RTTMax)

		if old, ok := m.prevStatus[k]; ok && old != c.Status {
			metrics.ProbeStatus.DeleteLabelValues(c.Src, c.Dst, string(old))
		}
		metrics.ProbeStatus.WithLabelValues(c.Src, c.Dst, string(c.Status)).Set(1)
		m.prevStatus[k] = c.Status

		if old, ok := m.prevViolation[k]; ok && old != c.Violation {
			metrics.PolicyViolation.DeleteLabelValues(c.Src, c.Dst, old)
			delete(m.prevViolation, k)
		}
		if c.Violation != "" {
			metrics.PolicyViolation.WithLabelValues(c.Src, c.Dst, c.Violation).Set(1)
			m.prevViolation[k] = c.Violation
		}
	}

	metrics.LastSweep.SetToCurrentTime()
	metrics.SweepDuration.Set(dur.Seconds())
	metrics.SweepsTotal.Inc()
	metrics.CellsTotal.Set(float64(len(cells)))
}

type alertPayload struct {
	Type    string       `json:"type"`
	At      time.Time    `json:"at"`
	Message string       `json:"message"`
	Cells   []model.Cell `json:"cells"`
}

func (m *Monitor) notify(changes []model.Cell, at time.Time) {
	if m.cfg.Alerts.Webhook == "" || len(changes) == 0 {
		return
	}
	payload := alertPayload{
		Type:    "state_change",
		At:      at,
		Message: "vlanmesh: connectivity state changed",
		Cells:   changes,
	}
	go func() {
		b, err := json.Marshal(payload)
		if err != nil {
			return
		}
		req, err := http.NewRequest(http.MethodPost, m.cfg.Alerts.Webhook, bytes.NewReader(b))
		if err != nil {
			return
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("User-Agent", "vlanmesh")
		resp, err := m.client.Do(req)
		if err != nil {
			slog.Warn("webhook failed", "err", err)
			return
		}
		resp.Body.Close()
	}()
}

func (m *Monitor) Snapshot() model.Snapshot {
	m.mu.RLock()
	defer m.mu.RUnlock()

	order := make(map[string]int, len(m.cfg.VLANS))
	for i, v := range m.cfg.VLANS {
		order[v.Name] = i
	}

	cells := make([]model.Cell, 0, len(m.cells))
	for _, c := range m.cells {
		cells = append(cells, c)
	}
	sort.Slice(cells, func(i, j int) bool {
		oi, oj := order[cells[i].Src], order[cells[j].Src]
		if oi != oj {
			return oi < oj
		}
		return order[cells[i].Dst] < order[cells[j].Dst]
	})

	sum := model.Summary{Sweeps: m.sweeps}
	for _, c := range cells {
		switch c.Status {
		case model.StatusOK:
			sum.OK++
		case model.StatusDegraded:
			sum.Degraded++
		case model.StatusRejected, model.StatusUnreachable, model.StatusTimeout:
			sum.Blocked++
		default:
			sum.Unknown++
		}
		if c.Violation != "" {
			sum.Violations++
		}
	}
	if !m.lastSweep.IsZero() {
		sum.LastSweep = m.lastSweep.UTC().Format(time.RFC3339)
	}

	vlans := make([]model.VLANInfo, 0, len(m.cfg.VLANS))
	for _, v := range m.cfg.VLANS {
		vlans = append(vlans, model.VLANInfo{
			Name:    v.Name,
			VLANID:  v.VLANID,
			Iface:   v.Iface,
			Src:     v.Src,
			Gateway: v.Gateway,
			Target:  m.cfg.Targets.For(v),
		})
	}

	pol := model.PolicyInfo{Default: m.cfg.Policy.Default}
	for _, r := range m.cfg.Policy.Rules {
		pol.Rules = append(pol.Rules, model.PolicyRule{From: r.From, To: r.To, Action: r.Action})
	}

	return model.Snapshot{
		GeneratedAt: time.Now().UTC(),
		Interval:    m.cfg.Interval.D().String(),
		Demo:        m.cfg.Demo,
		TargetsMode: m.cfg.Targets.Mode,
		Vlans:       vlans,
		Policy:      pol,
		Cells:       cells,
		Summary:     sum,
		Issues:      m.issues,
	}
}

// demoResult keeps the dashboard fully functional on a machine without the
// VLAN interfaces. It follows the declared policy, with a little noise.
func (m *Monitor) demoResult(j job) model.Result {
	r := model.Result{
		Started: time.Now(),
		SrcIP:   j.src.SrcIP(),
		DstIP:   j.dstIP,
		Sent:    m.cfg.Count,
	}
	roll := rand.Float64()
	lat := 0.25 + rand.Float64()*1.8

	if j.control {
		r.Status = model.StatusOK
		r.Recv = r.Sent
		r.RTTMin, r.RTTMax, r.RTTAvg = lat, lat+0.2, lat+0.1
		r.Duration = r.RTTAvg
		return r
	}

	exp, _ := m.cfg.Policy.Expected(j.src.Name, j.dst.Name)
	allowed := exp != "deny"

	if allowed {
		switch {
		case roll < 0.90:
			r.Status = model.StatusOK
			r.Recv = r.Sent
		case roll < 0.96:
			r.Status = model.StatusDegraded
			r.Recv = r.Sent - 1
			r.Err = "partial loss"
		default:
			r.Status = model.StatusTimeout
			r.Recv = 0
			r.Err = "no reply (simulated)"
		}
	} else {
		switch {
		case roll < 0.90:
			r.Status = model.StatusTimeout
			r.Recv = 0
			r.Err = "no reply (simulated)"
		case roll < 0.98:
			r.Status = model.StatusRejected
			r.Recv = 0
			r.ICMPType, r.ICMPCode = 3, 13
			r.Err = "icmp unreachable (type 3 code 13)"
		default:
			r.Status = model.StatusOK
			r.Recv = r.Sent
		}
	}

	if r.Recv > 0 {
		r.Loss = 1 - float64(r.Recv)/float64(r.Sent)
		r.RTTMin = lat
		r.RTTMax = lat + rand.Float64()*1.5
		r.RTTAvg = (r.RTTMin + r.RTTMax) / 2
	} else {
		r.Loss = 1
	}
	r.Duration = r.RTTAvg
	return r
}

package server

import (
	"encoding/json"
	"log/slog"
	"net/http"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"

	"vlanmesh/internal/metrics"
	"vlanmesh/internal/model"
	"vlanmesh/internal/monitor"
	"vlanmesh/internal/store"
	"vlanmesh/internal/web"
)

type Server struct {
	mon     *monitor.Monitor
	st      *store.Store
	version string
}

func New(mon *monitor.Monitor, st *store.Store, version string) http.Handler {
	s := &Server{mon: mon, st: st, version: version}
	mux := http.NewServeMux()

	mux.HandleFunc("GET /", s.index)
	mux.HandleFunc("GET /api/matrix", s.matrix)
	mux.HandleFunc("GET /api/history", s.history)
	mux.HandleFunc("GET /api/health", s.health)
	mux.Handle("GET /metrics", promhttp.HandlerFor(metrics.Registry, promhttp.HandlerOpts{}))

	return logging(mux)
}

func (s *Server) index(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Write(web.IndexHTML)
}

func (s *Server) matrix(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.mon.Snapshot())
}

func (s *Server) history(w http.ResponseWriter, r *http.Request) {
	src := r.URL.Query().Get("src")
	dst := r.URL.Query().Get("dst")
	if src == "" || dst == "" {
		http.Error(w, "src and dst are required", http.StatusBadRequest)
		return
	}
	limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
	cells, err := s.st.History(src, dst, limit)
	if err != nil {
		slog.Error("history query", "err", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	if cells == nil {
		cells = []model.Cell{}
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"src":     src,
		"dst":     dst,
		"results": cells,
	})
}

func (s *Server) health(w http.ResponseWriter, r *http.Request) {
	snap := s.mon.Snapshot()
	code := http.StatusOK
	if snap.Summary.OK+snap.Summary.Degraded+snap.Summary.Blocked+snap.Summary.Unknown == 0 {
		code = http.StatusServiceUnavailable
	}
	writeJSON(w, code, map[string]any{
		"status":       http.StatusText(code),
		"version":      s.version,
		"last_sweep":   snap.Summary.LastSweep,
		"violations":   snap.Summary.Violations,
		"demo":         snap.Demo,
	})
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(code)
	enc := json.NewEncoder(w)
	if err := enc.Encode(v); err != nil {
		slog.Error("encode response", "err", err)
	}
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		if r.URL.Path != "/api/matrix" && r.URL.Path != "/" {
			slog.Debug("http", "method", r.Method, "path", r.URL.Path, "dur", time.Since(start).Round(time.Millisecond))
		}
	})
}

