package config

import "testing"

func TestPolicyExpected(t *testing.T) {
	p := Policy{
		Default: "allow",
		Rules: []Rule{
			{From: "vlan10", To: "vlan20", Action: "deny"},
			{From: "vlan30", To: "*", Action: "deny"},
			{From: "*", To: "vlan99", Action: "deny"},
		},
	}
	cases := []struct {
		from, to, want string
	}{
		{"vlan10", "vlan20", "deny"},
		{"vlan10", "vlan30", "allow"},
		{"vlan30", "vlan10", "deny"},
		{"vlan30", "vlan20", "deny"},
		{"vlan10", "vlan99", "deny"},
		{"vlan40", "vlan50", "allow"},
	}
	for _, c := range cases {
		got, ok := p.Expected(c.from, c.to)
		if !ok {
			t.Fatalf("Expected(%s,%s): not found", c.from, c.to)
		}
		if got != c.want {
			t.Errorf("Expected(%s,%s)=%q want %q", c.from, c.to, got, c.want)
		}
	}
}

func TestPolicyNoDefault(t *testing.T) {
	p := Policy{Rules: []Rule{{From: "a", To: "b", Action: "deny"}}}
	if _, ok := p.Expected("a", "c"); ok {
		t.Fatal("expected unknown pair when no default")
	}
}

func validConfig() *Config {
	return &Config{
		Listen:   ":8080",
		Interval: Duration(30_000_000_000),
		Timeout:  Duration(1_000_000_000),
		Count:    3,
		VLANS: []VLAN{
			{Name: "vlan10", Iface: "eth1", Src: "192.168.10.5/24", Gateway: "192.168.10.254"},
			{Name: "vlan20", Iface: "eth2", Src: "192.168.20.5/24", Gateway: "192.168.20.254"},
		},
		Targets: Targets{Mode: "gateway"},
		Policy:  Policy{Default: "allow"},
	}
}

func TestValidate(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	if err := c.Validate(); err != nil {
		t.Fatalf("valid config rejected: %v", err)
	}
}

func TestValidateRejectsBadCIDR(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	c.VLANS[0].Src = "192.168.10.5"
	if err := c.Validate(); err == nil {
		t.Fatal("expected error for missing prefix")
	}
}

func TestValidateRejectsOverlapGateway(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	c.VLANS[0].Gateway = "192.168.20.254"
	if err := c.Validate(); err == nil {
		t.Fatal("expected error for gateway outside subnet")
	}
}

func TestVLANHelpers(t *testing.T) {
	v := VLAN{Src: "192.168.10.5/24"}
	if got := v.SrcIP(); got != "192.168.10.5" {
		t.Errorf("SrcIP=%q", got)
	}
	if got := v.Subnet(); got != "192.168.10.0/24" {
		t.Errorf("Subnet=%q", got)
	}
}

package probe

import (
	"encoding/binary"
	"testing"
)

func TestInnerIDSeq(t *testing.T) {
	// IPv4 header (20 bytes) + 8 bytes of the original ICMP echo.
	data := make([]byte, 28)
	data[0] = 0x45
	binary.BigEndian.PutUint16(data[20+4:20+6], 0xbeef)
	binary.BigEndian.PutUint16(data[20+6:20+8], 7)

	id, seq, ok := innerIDSeq(data)
	if !ok {
		t.Fatal("expected ok")
	}
	if id != 0xbeef || seq != 7 {
		t.Fatalf("id=%#x seq=%d", id, seq)
	}
}

func TestInnerIDSeqTooShort(t *testing.T) {
	if _, _, ok := innerIDSeq(make([]byte, 10)); ok {
		t.Fatal("expected false")
	}
}

func TestInnerIDSeqWithOptions(t *testing.T) {
	// IHL = 6 (24 bytes) to make sure we honour the header length.
	data := make([]byte, 32)
	data[0] = 0x46
	binary.BigEndian.PutUint16(data[24+4:24+6], 1)
	binary.BigEndian.PutUint16(data[24+6:24+8], 2)

	id, seq, ok := innerIDSeq(data)
	if !ok || id != 1 || seq != 2 {
		t.Fatalf("ok=%v id=%d seq=%d", ok, id, seq)
	}
}

