function buildMatrix(d){
  const t=el('matrix');
  t.innerHTML='';
  state.cells.clear();
  const hasInet=!!(d.internet&&d.internet.enabled);
  const head=document.createElement('thead');
  const hr=document.createElement('tr');
  const corner=document.createElement('th');
  corner.className='corner';
  corner.textContent='src \\ dst';
  hr.appendChild(corner);
  for(const v of d.vlans){
    const th=document.createElement('th');
    th.innerHTML='<span class="nm">'+esc(v.name)+'</span><span class="sub">'+esc(v.target||v.gateway)+'</span>';
    th.title=v.name+' — '+v.src+' — iface '+v.iface;
    hr.appendChild(th);
  }
  if(hasInet){
    const th=document.createElement('th');
    th.className='inet';
    th.innerHTML='<span class="nm">Internet</span><span class="sub">'+esc((d.internet.targets||[]).join(' · '))+'</span>';
    th.title='Accès Internet depuis chaque VLAN';
    hr.appendChild(th);
  }
  head.appendChild(hr); t.appendChild(head);

  const body=document.createElement('tbody');
  for(const src of d.vlans){
    const tr=document.createElement('tr');
    const th=document.createElement('th');
    th.className='rowh';
    th.innerHTML='<span class="nm">'+esc(src.name)+'</span><span class="sub">'+esc(src.iface)+' · '+esc(src.src)+'</span>';
    tr.appendChild(th);
    for(const dst of d.vlans){
      const td=document.createElement('td');
      td.className='cell s-unknown';
      td.dataset.src=src.name; td.dataset.dst=dst.name;
      if(src.name===dst.name) td.classList.add('self');
      td.addEventListener('click',()=>selectCell(src.name,dst.name));
      state.cells.set(src.name+'|'+dst.name,td);
      tr.appendChild(td);
    }
    if(hasInet){
      const td=document.createElement('td');
      td.className='cell inet s-unknown';
      td.dataset.src=src.name; td.dataset.dst='internet';
      td.addEventListener('click',()=>selectCell(src.name,'internet'));
      state.cells.set(src.name+'|internet',td);
      tr.appendChild(td);
    }
    body.appendChild(tr);
  }
  t.appendChild(body);
  state.matrixKey=matrixKey(d);
}

function matrixKey(d){
  const inet=(d.internet&&d.internet.enabled)?'|inet:'+((d.internet.targets||[]).join(',')):'';
  return d.vlans.map(v=>v.name).join('|')+inet;
}

function renderMatrix(d){
  const key=matrixKey(d);
  if(state.matrixKey!==key) buildMatrix(d);

