# Config de démonstration : aucune interface réseau requise.
#   go run . -config config.demo.yaml
# puis http://localhost:8080

listen: ":8080"
interval: 5s
count: 3
timeout: 1s
concurrency: 8
db: ./data/vlanmesh.db
retention: 24h
demo: true

vlans:
  - {name: vlan10, vlan_id: 10, iface: eth1, src: 192.168.10.5/24, gateway: 192.168.10.254}
  - {name: vlan20, vlan_id: 20, iface: eth2, src: 192.168.20.5/24, gateway: 192.168.20.254}
  - {name: vlan30, vlan_id: 30, iface: eth3, src: 192.168.30.5/24, gateway: 192.168.30.254}
  - {name: vlan40, vlan_id: 40, iface: eth4, src: 192.168.40.5/24, gateway: 192.168.40.254}
  - {name: vlan50, vlan_id: 50, iface: eth5, src: 192.168.50.5/24, gateway: 192.168.50.254}
  - {name: vlan60, vlan_id: 60, iface: eth6, src: 192.168.60.5/24, gateway: 192.168.60.254}
  - {name: vlan70, vlan_id: 70, iface: eth7, src: 192.168.70.5/24, gateway: 192.168.70.254}
  - {name: vlan80, vlan_id: 80, iface: eth8, src: 192.168.80.5/24, gateway: 192.168.80.254}

targets:
  mode: gateway

remotes:
  - {name: internet, label: Internet, targets: ["1.1.1.1", "8.8.8.8"]}
  - {name: dns, label: DNS, targets: ["192.168.1.4"]}
  - {name: proxy, label: "Reverse proxy", targets: ["192.168.50.1"]}

policy:
  default: allow
  rules:
    - {from: vlan10, to: vlan20, action: deny}
    - {from: vlan10, to: vlan30, action: deny}
    - {from: vlan20, to: vlan10, action: deny}
    - {from: vlan40, to: vlan50, action: deny}
    - {from: vlan50, to: vlan60, action: deny}
    - {from: vlan70, to: internet, action: deny}
    - {from: vlan80, to: internet, action: deny}
    - {from: vlan80, to: proxy, action: deny}

alerts:
  webhook: ""

package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestPolicyExpected(t *testing.T) {
	p := Policy{
		Default: "allow",
		Rules: []Rule{
			{From: "vlan10", To: "vlan20", Action: "deny"},
			{From: "vlan30", To: "*", Action: "deny"},
			{From: "*", To: "vlan99", Action: "deny"},
			{From: "vlan40", To: "dns", Action: "deny"},
		},
	}
	cases := []struct {
		from, to, want string
	}{
		{"vlan10", "vlan20", "deny"},
		{"vlan10", "vlan30", "allow"},
		{"vlan30", "vlan10", "deny"},
		{"vlan30", "vlan20", "deny"},
		{"vlan10", "vlan99", "deny"},
		{"vlan40", "dns", "deny"},
		{"vlan50", "dns", "allow"},
		{"vlan40", "vlan50", "allow"},
	}
	for _, c := range cases {
		got, ok := p.Expected(c.from, c.to)
		if !ok {
			t.Fatalf("Expected(%s,%s): not found", c.from, c.to)
		}
		if got != c.want {
			t.Errorf("Expected(%s,%s)=%q want %q", c.from, c.to, got, c.want)
		}
	}
}

func TestPolicyNoDefault(t *testing.T) {
	p := Policy{Rules: []Rule{{From: "a", To: "b", Action: "deny"}}}
	if _, ok := p.Expected("a", "c"); ok {
		t.Fatal("expected unknown pair when no default")
	}
}

func validConfig() *Config {
	return &Config{
		Listen:   ":8080",
		Interval: Duration(30_000_000_000),
		Timeout:  Duration(1_000_000_000),
		Count:    3,
		VLANS: []VLAN{
			{Name: "vlan10", Iface: "eth1", Src: "192.168.10.5/24", Gateway: "192.168.10.254"},
			{Name: "vlan20", Iface: "eth2", Src: "192.168.20.5/24", Gateway: "192.168.20.254"},
		},
		Targets: Targets{Mode: "gateway"},
		Policy:  Policy{Default: "allow"},
	}
}

func TestValidate(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	if err := c.Validate(); err != nil {
		t.Fatalf("valid config rejected: %v", err)
	}
}

func TestValidateRejectsBadCIDR(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	c.VLANS[0].Src = "192.168.10.5"
	if err := c.Validate(); err == nil {
		t.Fatal("expected error for missing prefix")
	}
}

func TestValidateRejectsOverlapGateway(t *testing.T) {
	c := validConfig()
	c.applyDefaults()
	c.VLANS[0].Gateway = "192.168.20.254"
	if err := c.Validate(); err == nil {
		t.Fatal("expected error for gateway outside subnet")
	}
}

func TestVLANHelpers(t *testing.T) {
	v := VLAN{Src: "192.168.10.5/24"}
	if got := v.SrcIP(); got != "192.168.10.5" {
		t.Errorf("SrcIP=%q", got)
	}
	if got := v.Subnet(); got != "192.168.10.0/24" {
		t.Errorf("Subnet=%q", got)
	}
}

func TestRemotes(t *testing.T) {
	c := validConfig()
	c.Remotes = []Remote{
		{Name: "internet", Targets: []string{"1.1.1.1", "8.8.8.8"}},
		{Name: "dns", Label: "DNS", Targets: []string{"192.168.1.4"}},
	}
	c.applyDefaults()
	if err := c.Validate(); err != nil {
		t.Fatalf("valid remotes rejected: %v", err)
	}
	if c.Remotes[0].Label != "internet" {
		t.Errorf("label should default to name, got %q", c.Remotes[0].Label)
	}
	if got := c.Remotes[1].DisplayName(); got != "DNS" {
		t.Errorf("DisplayName=%q", got)
	}
}

func TestRemoteNameCollidesWithVLAN(t *testing.T) {
	c := validConfig()
	c.Remotes = []Remote{{Name: "vlan10", Targets: []string{"192.168.1.4"}}}
	c.applyDefaults()
	if err := c.Validate(); err == nil {
		t.Fatal("expected collision between remote and VLAN names")
	}
}

func TestRemoteValidation(t *testing.T) {
	for _, tc := range []struct {
		name    string
		remote  Remote
		wantErr bool
	}{
		{"no target", Remote{Name: "x"}, true},
		{"bad target", Remote{Name: "x", Targets: []string{"dns.lan"}}, true},
		{"bad name", Remote{Name: "a b", Targets: []string{"1.1.1.1"}}, true},
		{"duplicate", Remote{Name: "x", Targets: []string{"1.1.1.1"}}, true},
		{"ok", Remote{Name: "ok-name", Targets: []string{"1.1.1.1"}}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := validConfig()
			c.Remotes = []Remote{tc.remote}
			if tc.name == "duplicate" {
				c.Remotes = append(c.Remotes, tc.remote)
			}
			c.applyDefaults()
			err := c.Validate()
			if tc.wantErr && err == nil {
				t.Fatal("expected error")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		})
	}
}

func TestLoadRejectsLegacyInternet(t *testing.T) {
	path := filepath.Join(t.TempDir(), "config.yaml")
	body := `
listen: ":8080"
vlans:
  - {name: vlan10, iface: eth1, src: 192.168.10.5/24, gateway: 192.168.10.254}
internet:
  enabled: true
  targets: ["1.1.1.1"]
policy: {default: allow}
`
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := Load(path)
	if err == nil {
		t.Fatal("expected legacy internet key to be rejected")
	}
	if !strings.Contains(err.Error(), "internet") {
		t.Fatalf("error should mention internet: %v", err)
	}
}

func TestLoadRejectsUnknownField(t *testing.T) {
	path := filepath.Join(t.TempDir(), "config.yaml")
	body := `
listen: ":8080"
nonsense: true
vlans:
  - {name: vlan10, iface: eth1, src: 192.168.10.5/24, gateway: 192.168.10.254}
policy: {default: allow}
`
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Load(path); err == nil {
		t.Fatal("expected unknown field to be rejected")
	}
}

package monitor

import (
	"context"
	"path/filepath"
	"testing"
	"time"

	"vlanmesh/internal/config"
	"vlanmesh/internal/model"
	"vlanmesh/internal/store"
)

func testConfig() *config.Config {
	return &config.Config{
		Interval:    config.Duration(5 * time.Second),
		Timeout:     config.Duration(time.Second),
		Count:       2,
		Concurrency: 4,
		Demo:        true,
		VLANS: []config.VLAN{
			{Name: "vlan10", Iface: "eth1", Src: "192.168.10.5/24", Gateway: "192.168.10.254"},
			{Name: "vlan20", Iface: "eth2", Src: "192.168.20.5/24", Gateway: "192.168.20.254"},
			{Name: "vlan30", Iface: "eth3", Src: "192.168.30.5/24", Gateway: "192.168.30.254"},
		},
		Targets: config.Targets{Mode: "gateway", Hosts: map[string]string{}},
		Remotes: []config.Remote{
			{Name: "internet", Label: "Internet", Targets: []string{"1.1.1.1"}},
			{Name: "dns", Label: "DNS", Targets: []string{"192.168.1.4"}},
		},
		Policy: config.Policy{
			Default: "allow",
			Rules: []config.Rule{
				{From: "vlan10", To: "vlan20", Action: "deny"},
				{From: "vlan20", To: "dns", Action: "deny"},
			},
		},
	}
}

func TestDemoSweep(t *testing.T) {
	st, err := store.Open(filepath.Join(t.TempDir(), "m.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer st.Close()

	m := New(testConfig(), st, nil)
	m.Sweep(context.Background())

	snap := m.Snapshot()
	// 3 VLANs: 3 controls + 6 directed pairs + 3*2 remote cells = 15.
	if len(snap.Cells) != 15 {
		t.Fatalf("cells: got %d, want 15", len(snap.Cells))
	}
	if len(snap.Remotes) != 2 {
		t.Errorf("remotes: got %d, want 2", len(snap.Remotes))
	}
	if snap.Summary.Sweeps != 1 {
		t.Errorf("sweeps=%d", snap.Summary.Sweeps)
	}

	wantRemoteExp := map[string]map[string]string{
		"internet": {"vlan10": "allow", "vlan20": "allow", "vlan30": "allow"},
		"dns":      {"vlan10": "allow", "vlan20": "deny", "vlan30": "allow"},
	}
	remoteCells := 0
	for _, c := range snap.Cells {
		if want, ok := wantRemoteExp[c.Dst]; ok {
			remoteCells++
			if c.Expected != want[c.Src] {
				t.Errorf("remote %s/%s: expected=%q, want %q", c.Dst, c.Src, c.Expected, want[c.Src])
			}
			if c.SrcIP == "" || c.DstIP == "" {
				t.Errorf("remote %s/%s: missing src/dst ip", c.Dst, c.Src)
			}
		}
	}
	if remoteCells != 6 {
		t.Fatalf("remote cells: got %d, want 6", remoteCells)
	}

	for _, c := range snap.Cells {
		if c.Src == c.Dst {
			if c.Status != model.StatusOK {
				t.Errorf("control %s: status=%s, want ok", c.Src, c.Status)
			}
			if c.Expected != "" || c.Violation != "" {
				t.Errorf("control %s: expected/violation should be empty", c.Src)
			}
			continue
		}
		switch {
		case c.Expected == "allow" && !c.Status.Reachable():
			if c.Violation != "unexpected_deny" {
				t.Errorf("%s->%s: allow+blocked must be unexpected_deny, got %q", c.Src, c.Dst, c.Violation)
			}
		case c.Expected == "deny" && c.Status.Reachable():
			if c.Violation != "unexpected_allow" {
				t.Errorf("%s->%s: deny+reachable must be unexpected_allow, got %q", c.Src, c.Dst, c.Violation)
			}
		default:
			if c.Violation != "" {
				t.Errorf("%s->%s: unexpected violation %q", c.Src, c.Dst, c.Violation)
			}
		}
	}

	// History is persisted and reloadable.
	hist, err := st.History("vlan10", "vlan20", 10)
	if err != nil {
		t.Fatal(err)
	}
	if len(hist) != 1 {
		t.Fatalf("history: got %d, want 1", len(hist))
	}
	if hist, _ := st.History("vlan10", "dns", 10); len(hist) != 1 {
		t.Fatalf("remote history: got %d, want 1", len(hist))
	}
}

func TestSnapshotBeforeSweep(t *testing.T) {
	st, err := store.Open(filepath.Join(t.TempDir(), "m.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer st.Close()

	m := New(testConfig(), st, []string{"test issue"})
	snap := m.Snapshot()
	if len(snap.Cells) != 0 {
		t.Errorf("cells: got %d, want 0", len(snap.Cells))
	}
	if len(snap.Vlans) != 3 {
		t.Errorf("vlans: got %d", len(snap.Vlans))
	}
	if len(snap.Remotes) != 2 {
		t.Errorf("remotes: got %d", len(snap.Remotes))
	}
	if len(snap.Issues) != 1 {
		t.Errorf("issues: got %d", len(snap.Issues))
	}
}

